// === Tab: mySketch ===
let S;

function setup() {
	describe("grid of randomly subdived 5x5 cells");

	let w = windowWidth, h = windowHeight;
	S = min(w, h);
	let num = 0;
	while (S > 6) {
		S /= 6;
		num++;
	}
	for (let i = 0; i < num; i++) {
		S = ~~S * 6;
	}
	// console.log(w, h, S, num, S/num);
	S/=num;
	w=S*~~(w/S);
	h=S*~~(h/S);
	// console.log(w, h);

	createCanvas(w, h);
	noStroke();

	// noLoop() removed for animation
}

function draw() {
	background(32);
	for (let y = 0; y < height; y+=S) {		
		for (let x = 0; x < width; x+=S) {
			drawTile(x, y, S)
		}
	}
}

function mousePressed() {
	if (mouseButton !== RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1*width) {
		draw();
	}
}

function drawTile(x, y, S) {
	if (S > 25 && random()<0.5) {
		S /= 2;
		drawTile(x, y, S);
		drawTile(x+S, y, S);
		drawTile(x, y+S, S);
		drawTile(x+S, y+S, S);
	} else {		
		fill(random(200, 300), random(200), random(100, 200));
		rect(x, y, S);

		var num = 5;
		S/=(num+1); x+=S/2; y+= S/2;

		let arr = Array(num*num);
		for (let k = 0; k < arr.length; k++) { 
			arr[k] = random() < (k%2 ? 0.6 : 0.8); // keep foundation with higher probability
		}
		arr[6] = false; arr[8] = false; arr[16] = false; arr[18] = false; // delete cells direct diagional to the center

		for (let j = 0, k = 0; j < num; j++) {			
			for (let i = 0; i < num; i++, k++) {
				if (arr[k]) {
					fill(255, random(150, 200));
					rect(x+j*S, y+i*S, S);
				}
			}
		}
	}
}
